LANGS = ["en", "es", "fr", "pt", "de", "zh", "ar", "th"]

def tr(data):
    """Build a Lang record from a dict with at least 'en' key. Missing langs fall back to en."""
    return "{ " + ", ".join(f'{l}: {json.dumps(data.get(l, data["en"]))}' for l in LANGS) + " }"

def tra(data):
    """Build a Lang record for arrays (td)."""
    return "{ " + ", ".join(f'{l}: {json.dumps(data.get(l, data["en"]))}' for l in LANGS) + " }"

