# Generate lang-store.ts
lines = []
lines.append("import { create } from 'zustand';")
lines.append("import { persist } from 'zustand/middleware';")
lines.append("")
lines.append("type Lang = 'en' | 'es' | 'fr' | 'pt' | 'de' | 'zh' | 'ar' | 'th';")
lines.append("")
lines.append("interface LangStore {")
lines.append("  lang: Lang;")
lines.append("  setLang: (lang: Lang) => void;")
lines.append("}")
lines.append("")
lines.append("export const useLangStore = create<LangStore>()(")
lines.append("  persist(")
lines.append("    (set) => ({ lang: 'en', setLang: (lang) => set({ lang }) }),")
lines.append("    { name: 'qfs-lang' }")
lines.append("  )")
lines.append(");")
lines.append("")
lines.append("const t: Record<string, Record<Lang, string>> = {")

# Sort keys alphabetically
for key in sorted(t_keys.keys()):
    val = t_keys[key]
    lines.append(f'  "{key}": {{ {", ".join(f"{l}: {json.dumps(val.get(l, val["en"]))}" for l in LANGS)} }},')

lines.append("};")
lines.append("")
lines.append("const td: Record<string, Record<Lang, string[]>> = {")

for key in sorted(td_keys.keys()):
    val = td_keys[key]
    lines.append(f'  "{key}": {{')
    for l in LANGS:
        arr = val.get(l, val["en"])
        lines.append(f'    {l}: {json.dumps(arr, ensure_ascii=False)},')
    lines.append("  },")

lines.append("};")
lines.append("")
lines.append("export function useT() {")
lines.append("  const { lang } = useLangStore();")
lines.append("  return (key: string): string => t[key]?.[lang] ?? key;")
lines.append("}")
lines.append("")
lines.append("export function useTD() {")
lines.append("  const { lang } = useLangStore();")
lines.append("  return (key: string): string[] => td[key]?.[lang] ?? [];")
lines.append("}")

with open('/home/z/my-project/src/store/lang-store.ts', 'w') as f:
    f.write('\n'.join(lines))

print("lang-store.ts written successfully with", len(t_keys), "string keys and", len(td_keys), "array keys")
